writing.exampleCode:
let text = "café";
let decomposed = "e\u{301}";
assert_eq!(text.len(), 5);
assert_eq!(text.chars().count(), 4);
assert_eq!(decomposed.len(), 3);
assert_eq!(decomposed.chars().count(), 2);
assert_eq!(text.get(3..5), Some("é"));
assert_eq!(text.get(3..4), None);
println!("café: {} bytes, {} scalars", text.len(), text.chars().count());

